uniform float density : 0.0 .. 1.0 = 0.4;
uniform float speed   : 0.0 .. 5.0 = 1.0;
uniform vec3  tint    : color = 1.0, 0.9, 0.6;

struct Firefly {
  fixed phase;
  fixed rate;
  fixed pos;
  fixed blink;
};
state Firefly flies[12];
state bool  inited;

void update() {
  if (!inited) {
    for (int i = 0; i < 12; i = i + 1) {
      flies[i].phase = fixed(hash(float(i)));
      flies[i].rate  = fixed(0.25 + hash(float(i) * 3.0) * 0.5);
      flies[i].pos   = fixed(hash(float(i) * 7.0));
      flies[i].blink = fixed(hash(float(i) * 11.0));
    }
    inited = true;
  }
  for (int i = 0; i < 12; i = i + 1) {
    flies[i].phase = fract(flies[i].phase + fixed(dt * speed * flies[i].rate));
  }
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  vec3  c = vec3(0.0, 0.0, 0.0);
  for (int i = 0; i < 12; i = i + 1) {
    fixed d = abs(s - flies[i].pos);
    if (d < fixed(0.0625)) {
      fixed env = fixed(1.0) - d * fixed(16.0);
      fixed b   = sin(flies[i].phase * fixed(6.2831853));
      fixed bright = clamp((b * fixed(0.5) + fixed(0.5)) * flies[i].blink * fixed(density), fixed(0.0), fixed(1.0));
      c = c + vec3(float(bright * flies[i].blink), float(bright * flies[i].blink * fixed(0.9)), float(bright * flies[i].blink * fixed(0.6)));
    }
  }
  return c;
}
